function learningModule(id){const f={flash:flashLab,quiz:quizLab,interview:interviewLab,broken:brokenLab,design:designLab,cheat:cheatLab,more:moreLab,ccna:courseLab,ccnp:courseLab,ccie:courseLab,roadmap:roadmapLab,about:aboutLab};if(!f[id])return false;f[id](id);return true;}
function flashLab(){let deck=[...QA],i=0,correct=0,wrong=0,revealed=false;$('surface').innerHTML=card('Study deck',`<div class="fields">${select('flash-level','Level',['All','CCNA','CCNP','CCIE'])}</div><div class="actions">${btn('flash-shuffle','Shuffle')}${btn('flash-reset','Restart')}</div>${out('flash-score')}<button id="flash-card" class="flash" style="width:100%"></button><div class="actions">${btn('flash-reveal','Reveal answer',true)}${btn('flash-right','I knew it')}${btn('flash-wrong','Review again')}</div>${out()}`);const draw=()=>{$('flash-score').innerHTML=`<div class="score"><span>Correct: ${correct}</span><span>Review: ${wrong}</span><span>Remaining: ${Math.max(0,deck.length-i)}</span></div>`;const q=deck[i];$('flash-card').textContent=q?(revealed?q[3]:q[2]):'Deck complete — restart or choose another level.';$('flash-right').disabled=!q||!revealed;$('flash-wrong').disabled=!q||!revealed;$('output').innerHTML=q?hint(q[0]+' · '+q[1]+(revealed?' · Answer shown':' · Think through your answer before revealing it.')):'';};const reset=()=>{deck=QA.filter(q=>$('flash-level').value==='All'||q[0]===$('flash-level').value);i=correct=wrong=0;revealed=false;draw();};action('flash-reveal',()=>{revealed=true;draw();});$('flash-card').onclick=()=>{revealed=!revealed;draw();};action('flash-right',()=>{correct++;i++;revealed=false;draw();});action('flash-wrong',()=>{wrong++;i++;revealed=false;draw();});action('flash-reset',reset);action('flash-shuffle',()=>{for(let j=deck.length-1;j>0;j--){const k=Net.randomInt(j+1);[deck[j],deck[k]]=[deck[k],deck[j]];}i=correct=wrong=0;revealed=false;draw();});$('flash-level').onchange=reset;draw();}
function quizLab(){let deck=[...QA],i=0,score=0,answered=0,locked=false,options=[];$('surface').innerHTML=card('Knowledge check',`<div class="fields">${select('quiz-level','Difficulty',['All','CCNA','CCNP','CCIE'])}</div>${out('quiz-score')}${out('quiz-question')}${out('quiz-options')}${out()}<div class="actions">${btn('quiz-next','Next question',true)}${btn('quiz-reset','Reset quiz')}</div>`);const draw=()=>{locked=false;$('output').innerHTML='';$('quiz-next').disabled=true;$('quiz-score').innerHTML=`<div class="score"><span>Score: ${score} / ${answered}</span><span>Question ${i+1} / ${deck.length}</span></div>`;const q=deck[i];$('quiz-question').innerHTML=`<h3>${esc(q[2])}</h3><p>${q[0]} · ${q[1]}</p>`;options=[...q[4]].sort(()=>Math.random()-.5);$('quiz-options').innerHTML=options.map((o,k)=>`<button class="answer-option" data-option="${k}">${esc(o)}</button>`).join('');$('quiz-options').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;answered++;const yes=options[Number(b.dataset.option)]===q[4][0];if(yes)score++;b.classList.add(yes?'positive':'negative');$('output').innerHTML=hint(`${yes?'Correct.':'Review this one.'} ${esc(q[3])}`);$('quiz-next').disabled=false;$('quiz-score').innerHTML=`<div class="score"><span>Score: ${score} / ${answered}</span><span>Accuracy: ${Math.round(score/answered*100)}%</span></div>`;});};const reset=()=>{deck=QA.filter(q=>$('quiz-level').value==='All'||q[0]===$('quiz-level').value);i=score=answered=0;draw();};action('quiz-next',()=>{if(i+1===deck.length){$('quiz-question').innerHTML='<h3>Quiz complete</h3>';$('quiz-options').innerHTML='';$('quiz-next').disabled=true;$('output').innerHTML=hint(`You scored ${score} out of ${answered}. Restart to practice again.`);return;}i++;draw();});action('quiz-reset',reset);$('quiz-level').onchange=reset;draw();}
function interviewLab(){$('surface').innerHTML=card('Interview question bank',`<div class="fields">${select('interview-level','Level',['All','CCNA','CCNP','CCIE'])}${input('interview-search','Topic or keyword','')}</div>${out()}`);const draw=()=>{const level=$('interview-level').value,q=$('interview-search').value.toLowerCase(),a=QA.filter(x=>(level==='All'||x[0]===level)&&x.join(' ').toLowerCase().includes(q));$('output').innerHTML=hint(a.length+' questions. Explain the mechanism, then give a verification command or failure case.')+a.map(x=>`<details class="lesson"><summary><small class="positive">${x[0]} · ${x[1]}</small><br>${esc(x[2])}</summary><p>${esc(x[3])}</p><p>Follow-up: describe what evidence you would gather on a real device before changing its configuration.</p></details>`).join('');};$('interview-level').onchange=draw;$('interview-search').oninput=draw;draw();}
const CHALLENGES=[
 ['OSPF','MTU disagreement','Neighbors remain in ExStart. Both links can ping.','R1: interface Gi0/0\n ip mtu 1500\n ip ospf 1 area 0\n\nR2: interface Gi0/0\n ip mtu 1400\n ip ospf 1 area 0','Match the interface MTUs after checking the path.','Matching interface MTUs','Change the DNS server','Increase BGP local preference','Advertise a default route'],
 ['OSPF','Area mismatch','No OSPF adjacency forms on the direct link.','R1: ip ospf 1 area 0\nR2: ip ospf 1 area 1','Use the same area ID on the directly connected segment.','Same area ID','Different router process number','A static default only','STP priority zero'],
 ['OSPF','Timer mismatch','Neighbors are not visible despite physical connectivity.','R1: ip ospf hello-interval 10\n    ip ospf dead-interval 40\nR2: ip ospf hello-interval 5\n    ip ospf dead-interval 20','Match Hello and dead intervals on the segment.','Match Hello/dead timers','Disable all TCP ports','Use different VLANs','Change router hostname'],
 ['OSPF','Duplicate router IDs','Two routers share a manual router ID.','R1: router-id 1.1.1.1\nR2: router-id 1.1.1.1','Configure unique router IDs and plan any required process restart.','Unique router IDs','Identical MAC addresses','Double the MTU','Enable Telnet'],
 ['BGP','Wrong remote AS','The TCP session is reachable but BGP does not establish.','R1: router bgp 65001\n neighbor 192.0.2.2 remote-as 65003\n\nR2: router bgp 65002','Match remote-as to the actual peer ASN.','Correct remote-as','Change the native VLAN everywhere','Increase OSPF cost','Enable DHCP snooping'],
 ['BGP','Unreachable next hop','The route is in BGP but cannot be installed.','198.51.100.0/24 next hop 192.0.2.1\nRIB: no route to 192.0.2.1','Provide recursive reachability or apply next-hop-self on the proper advertisement.','Resolve NEXT_HOP','Use a larger MED','Remove all specific routes','Change the DNS TTL'],
 ['BGP','Prefix length mismatch','A intended /24 is denied by the inbound policy.','ip prefix-list IN permit 10.0.0.0/8\nReceived: 10.1.2.0/24','Use an appropriate le/ge qualifier; an unqualified /8 matches only the /8.','Add a suitable le qualifier','Change UDP port 53','Use an identical AS path','Decrease TCP window'],
 ['BGP','Missing originating route','The configured network statement advertises nothing.','network 203.0.113.0 mask 255.255.255.0\nRIB: only 203.0.113.0/25 present','Ensure the exact prefix and mask exists in the routing table and is intentional.','Install the intended exact prefix','Add an arbitrary /32','Disable routing','Change the MAC OUI'],
 ['EIGRP','No feasible successor','The alternate is not a precomputed loop-free backup.','Current FD: 1000\nAlternate RD: 1200\nAlternate total distance: 1400','RD is not less than FD; a diffusing computation can be necessary.','RD fails the feasibility condition','The alternate is always a loop','Use a higher IP TTL','The MTU is always wrong'],
 ['EIGRP','K-value mismatch','Neighbor formation fails with a K-value warning.','R1: K1=1 K3=1\nR2: K1=1 K3=0','Use compatible K values on both peers.','Match K values','Change HTTP port','Disable ARP','Raise STP cost'],
 ['Security','ACL ordering','An intended HTTPS exception never matches.','deny ip any any\npermit tcp 192.168.10.0 0.0.0.255 any eq 443','Place the specific permit before the broad deny.','Reorder the ACL','Change DNS','Use a larger MTU','Remove the gateway'],
 ['Security','Wrong wildcard','An ACL permits more hosts than intended.','Intended: 192.168.10.0/24\npermit ip 192.168.10.0 0.0.255.255 any','Use 0.0.0.255 for a /24 contiguous match.','Correct wildcard to 0.0.0.255','Use 255.255.255.0 wildcard','Increase MED','Enable IPv6 multicast'],
 ['DHCP','Missing relay','Clients on a remote VLAN get no DHCP offer.','Client VLAN 10: 10.10.10.0/24\nServer: 10.20.20.10\nGateway interface: no helper configured','Configure a relay/helper and ensure the server has the correct scope.','Add DHCP relay and matching scope','Change BGP community','Set STP cost 1','Use a default DNS record'],
 ['Switching','Native VLAN mismatch','An untagged frame is classified into different VLANs at each end.','SW1 trunk native VLAN 10\nSW2 trunk native VLAN 20','Align native VLAN behavior on the trunk and apply the intended hardening policy.','Match native VLAN configuration','Use a larger subnet mask','Set BGP weight 100','Set OSPF router ID 0'],
 ['Routing','Missing return route','Requests reach the server, but replies never reach the client.','Client: 10.1.0.10\nServer default route: missing\nForward path: working','Verify and install the intended return path; reachability is bidirectional.','Provide return routing','Change the client hostname','Increase DNS TTL','Use a new ARP broadcast address']
];
function brokenLab(){let index=0,solved=new Set();$('surface').innerHTML=card('Troubleshooting scenarios',select('challenge-filter','Topic',['All',...new Set(CHALLENGES.map(x=>x[0]))])+out('challenge-list'))+card('Find the cause',out('challenge')+out());const load=i=>{index=i;const c=CHALLENGES[i];$('challenge').innerHTML=`<h3>${esc(c[1])}</h3><p>${esc(c[2])}</p><pre>${esc(c[3])}</pre><p>Which change or explanation addresses the root cause?</p>`+c.slice(5).map((x,k)=>`<button class="answer-option" data-fix="${k}">${esc(x)}</button>`).join('');$('output').innerHTML='';$('challenge').querySelectorAll('button').forEach(b=>b.onclick=()=>{const yes=Number(b.dataset.fix)===0;if(yes)solved.add(i);$('output').innerHTML=hint((yes?'Correct. ':'Try again. ')+esc(c[4]));draw();});};const draw=()=>{$('challenge-list').innerHTML=hint(`Solved ${solved.size} / ${CHALLENGES.length}`)+`<div class="chips">${CHALLENGES.map((c,i)=>[$('challenge-filter').value==='All'||c[0]===$('challenge-filter').value?`<button data-challenge="${i}" class="${index===i?'active':''}">${solved.has(i)?'✓ ':''}${esc(c[1])}</button>`:'']).join('')}</div>`;$('challenge-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{load(Number(b.dataset.challenge));draw();});};$('challenge-filter').onchange=draw;load(0);draw();}
function designLab(){const questions=[['Number of sites',['Single campus','2–5 sites','6–20 sites','20+ sites']],['Users per site',['Under 50','50–250','250–1000','Over 1000']],['Availability target',['Single path acceptable','Redundant gateway and uplinks','Dual providers and resilient core']],['Primary workload',['General office','Voice and video','Data center / applications','Mixed enterprise']],['Operations preference',['Simple static routing','Dynamic routing','Automation and centrally managed policy']]];let step=0,answers=[];$('surface').innerHTML=card('Network design interview',out());const draw=()=>{if(step<questions.length){const q=questions[step];$('output').innerHTML=`<div class="eyebrow">Step ${step+1} of ${questions.length}</div><h3>${q[0]}</h3>${q[1].map((x,i)=>`<button class="answer-option" data-design="${i}">${x}</button>`).join('')}${step?btn('design-back','Back'):''}`;$('output').querySelectorAll('[data-design]').forEach(b=>b.onclick=()=>{answers[step]=Number(b.dataset.design);step++;draw();});if(step)action('design-back',()=>{step--;draw();});}else{const redundant=answers[2]>0,large=answers[0]>1||answers[1]>1;const text=`PARAM CHAWLA — NETWORK DESIGN NOTES\n\n${questions.map((q,i)=>q[0]+': '+q[1][answers[i]]).join('\n')}\n\nArchitecture: ${large?'Hierarchical access / distribution / core':'Access with a collapsed distribution/core'}\nRouting: ${answers[4]===0&&!large?'Static routes for a simple stable topology':'OSPF or another suitable IGP inside the enterprise; use BGP for provider/policy boundaries'}\nAvailability: ${redundant?'Redundant gateways, uplinks and independent failure domains':'Single-path design, with its availability limitations documented'}\nSegmentation: Separate user, server, management and guest VLANs.\nAddressing: Use VLSM and leave growth space.\nSecurity: Least-privilege ACLs, protected management, logging and change control.\nValidation: Test normal and failure paths, return routing, DNS/DHCP and application performance.`;$('output').innerHTML=`<pre>${esc(text)}</pre>`+hint('This is a starting architecture checklist. Real design requires traffic measurements, physical constraints, failure analysis and vendor sizing.')+`<div class="actions">${btn('design-save','Download notes',true)}${btn('design-restart','Start again')}</div>`;action('design-save',()=>download('param-network-design.txt',text));action('design-restart',()=>{step=0;answers=[];draw();});}};draw();}
function cheatLab(){$('surface').innerHTML=card('IPv4 prefix table',table(['Prefix','Mask','Addresses','Usable hosts','Wildcard'],Array.from({length:33},(_,i)=>{const n=Net.subnet('0.0.0.0',32-i);return['/'+n.p,n.mask,n.size.toLocaleString(),n.hosts.toLocaleString(),n.wildcard];})))+card('Protocol reference',table(['Protocol','Transport / identifier','Quick inspection'],[['OSPF','IP protocol 89','show ip ospf neighbor'],['BGP','TCP 179','show bgp summary'],['EIGRP','IP protocol 88','show ip eigrp neighbors'],['IS-IS','Layer 2','show isis neighbors'],['DHCPv4','UDP 67 / 68','show ip dhcp binding'],['DNS','UDP/TCP 53','dig / nslookup'],['ARP','EtherType 0x0806','show ip arp']]));}
function moreLab(){$('surface').innerHTML=card('Wildcard and host requirement',`<div class="fields">${input('more-prefix','Prefix',24,'number','min="0" max="32"')}${input('more-hosts','Required hosts',50,'number','min="1"')}</div>${btn('more-run','Calculate',true)}${out()}`)+card('List host addresses',input('host-block','Small subnet','192.168.10.0/28')+`<div class="actions">${btn('host-list','List addresses')}</div>${out('host-output')}`);action('more-run',()=>{const n=Net.subnet('0.0.0.0',$('more-prefix').value),required=Number($('more-hosts').value);if(!Number.isInteger(required)||required<1||required>2**32-2)throw Error('Use a positive IPv4 host requirement.');const size=2**Math.ceil(Math.log2(required+2)),p=32-Math.log2(size);$('output').innerHTML=stats([['Mask',n.mask],['Wildcard',n.wildcard],['Recommended conventional prefix','/'+p],['Capacity',size-2]])+hint('The size finder reserves network and broadcast addresses. A point-to-point design may use a /31 separately.');});action('host-list',()=>{const n=Net.subnet($('host-block').value);if(n.size>1024)throw Error('Choose a /22 or longer to keep the address list manageable.');$('host-output').innerHTML=table(['Address','Role'],Array.from({length:n.size},(_,i)=>[Net.str(n.start+i),n.p<31&&i===0?'Network':n.p<31&&i===n.size-1?'Broadcast':'Usable']));});$('more-run').click();}
const LESSONS={
 'OSI & TCP/IP':['Use layers to localize a fault: link, addressing, routing, transport, then the application. Encapsulation adds headers as data moves down a stack; the receiver removes and interprets them. The OSI model is a vocabulary, not a requirement that every implementation have seven separate components.','Follow a browser request through Ethernet, IP and TCP. Identify which address changes at a router and which usually remains end to end.','decoder','ip route get 192.0.2.10'],
 'Ethernet & ARP':['A switch learns source MAC addresses on ingress ports. Known unicast frames use the MAC table; broadcasts remain in the VLAN. ARP maps an IPv4 next-hop address to a local-link MAC. A host going off-subnet resolves its gateway MAC.','Walk a request/reply and explain why ARP does not cross a router as an ordinary broadcast.','arp','show mac address-table\nshow ip arp'],
 'Switching & STP':['Redundant Layer 2 links can create loops because Ethernet frames have no router-style TTL. STP elects a root and blocks redundant forwarding paths. RSTP adds alternate roles and rapid transitions when its conditions are satisfied.','Change bridge priorities and costs; identify the root and blocked/alternate ports.','stp','show spanning-tree'],
 'VLANs & Trunks':['VLANs define separate Layer 2 broadcast domains. Access ports normally carry one untagged VLAN; trunks carry multiple VLANs using tags. Native VLAN behavior must agree at both ends. Inter-VLAN traffic requires routing.','Inspect the VLAN ID, PCP and tag overhead, then explain where a native mismatch changes frame classification.','vlan','show interfaces trunk\nshow vlan brief'],
 'IPv4 Addressing':['IPv4 contains 32 bits. A prefix defines the network boundary, independent of historical address classes. RFC 1918 private ranges need appropriate routing or translation for internet connectivity. Special-purpose addresses have uses beyond ordinary unicast.','Classify private, loopback, link-local and documentation addresses.','classes','show ip interface brief'],
 'Subnetting & VLSM':['A prefix fixes the high-order bits; remaining bits select an address in the block. Networks must be aligned to their block size. VLSM allocates different sized blocks, generally placing the largest first. A /31 and /32 have special host-count semantics.','Allocate user, server and management segments; verify no overlap and retain growth space.','vlsm','show ip route connected'],
 'IPv6 & NDP':['IPv6 has eight 16-bit groups. Compression removes leading zeros and replaces one longest run of zero groups. Neighbor Discovery uses ICMPv6 for address resolution and router discovery. SLAAC generally uses a /64 interface prefix, with modern privacy or stable address generation.','Expand and compress an address; divide a /48 into /64s and inspect a modified EUI-64 example.','ipv6','show ipv6 interface\nshow ipv6 neighbors'],
 'Static Routing':['Forwarding uses the longest matching prefix. For the same destination prefix, route preference and metrics determine installed routes. A default route is a fallback; a summary may cover destinations that have no specific route. Return routing is required.','Paste a routing table and test which entry forwards a destination address.','routes','show ip route\nshow ip route 203.0.113.10'],
 'OSPF Fundamentals':['OSPF discovers neighbors using Hellos, exchanges database information, then calculates shortest paths. Adjacency depends on compatible area, timers, authentication and other parameters. Broadcast networks use a DR/BDR to reduce adjacency and flooding overhead.','Walk Down → Init → 2-Way → ExStart → Exchange → Loading → Full.','ospf-neighbor','show ip ospf neighbor\nshow ip ospf interface'],
 'DHCP & DNS':['DHCP leases an address and supplies options such as gateway and DNS servers. A relay bridges the broadcast boundary between clients and a remote server. DNS resolves names using records and caches; transport reachability alone does not prove correct resolution.','Walk DORA, then a recursive DNS lookup and explain the function of the lease and TTL.','dhcp','show ip dhcp binding\nnslookup lab.example'],
 'TCP & UDP':['TCP offers a reliable ordered byte stream with sequence and acknowledgment numbers. SYN and FIN consume sequence space. UDP carries independent datagrams without TCP’s connection and retransmission machinery. Application requirements determine the appropriate behavior.','Step through a handshake, data exchange, retransmission and graceful close.','tcp','ss -tan\nshow tcp brief'],
 'ACLs':['ACLs evaluate conditions in order and stop at the first match. Standard IPv4 ACLs match source addressing; extended ACLs can match source, destination, protocol and ports. Wildcard masks describe which bits to ignore. Rule placement and direction determine the effect.','Create a specific HTTPS permit followed by a deny, and test permitted and denied packets.','acl','show access-lists\nshow ip interface'],
 'NAT & PAT':['Static NAT supplies a persistent address mapping; dynamic NAT allocates from a pool. PAT distinguishes sessions using ports as well as addresses. Translation does not replace filtering or correct return routing. Application payloads and asymmetric routing can complicate behavior.','Compare an inside-local socket with its inside-global representation.','nat','show ip nat translations\nshow ip nat statistics'],
 'Wireless Basics':['Wireless access shares airtime and introduces RF constraints that wired switching does not have. Channel width, interference, signal quality and client capabilities affect throughput. Association and authentication precede useful IP traffic. Separate RF faults from DHCP, DNS and policy faults.','Use the latency simulator to compare LAN and variable-delay profiles; explain why this does not measure real RF conditions.','ping','Inspect controller client state, RSSI, SNR and channel utilization.'],
 'Network Security':['Protect management access, segment users and services, enforce least privilege and collect evidence through logs. Stateful inspection and authentication complement ACLs. Use encrypted management protocols and deliberate trust boundaries. A simulated allow result is not a complete security assessment.','Test ACL ordering, then trace certificate verification in the TLS lab.','tls','show access-lists\nshow logging'],
 'Automation Basics':['Treat configurations as structured, reviewable changes. Read state before writing, validate inputs and check the resulting operational state. NETCONF/RESTCONF and vendor APIs can supply structured data; text parsing has format and platform limits. Keep credentials separate from source.','Export an ACL and interface plan, then identify what must be customized and verified on the target platform.','acl','Compare intended configuration with running and operational state.'],
 'Advanced OSPF':['Type 1/2 LSAs describe area topology. ABRs originate inter-area summaries; ASBRs originate external information. Stub variants control which external and summary information enters an area. A local RIB filter is different from stopping LSDB flooding.','Compare area types, inspect LSA scope and run SPF after a link failure.','area','show ip ospf database\nshow ip ospf border-routers'],
 'BGP Policy':['BGP selects usable routes using path attributes and operator policy. Local preference normally selects an exit inside an AS; MED can express a preferred entry when comparable. Communities mark routes for policy. Import and export policies must be reviewed separately.','Change path attributes, then apply prefix-list and community controls.','bgp-best','show bgp ipv4 unicast\nshow route-map'],
 'BGP Troubleshooting':['First establish transport and session health. Verify peer ASN, source address, TTL/security and negotiated capabilities. Next check route origination, import policy and NEXT_HOP reachability. A route in Adj-RIB-In may not be eligible for selection or installation.','Diagnose Active state, an exact-prefix origination mismatch and an unreachable next hop.','broken','show bgp summary\nshow bgp neighbors'],
 MPLS:['MPLS forwarding looks up a label and can push, swap or pop label stacks. Transport labels deliver traffic to an egress; service labels can select a VPN forwarding context. PHP can remove the transport label before the egress. Control-plane label distribution and the underlying IGP must be healthy.','Walk a basic LSP and then a VPN stack; identify which label changes at each hop.','mpls','show mpls forwarding-table\nshow mpls ldp neighbor'],
 QoS:['QoS manages contention; it does not create bandwidth. Classify and mark traffic, queue it according to policy, and distinguish shaping from policing. Serialization delay depends on packet size and rate. Applications can be harmed by jitter or loss even when average latency appears acceptable.','Calculate serialization delay and bandwidth-delay product, then compare congested latency.','units','show policy-map interface'],
 'IPsec VPN':['IPsec authenticates and protects selected traffic with security associations. IKE negotiates identity and cryptographic policy; ESP carries protected payload. Encapsulation reduces usable inner MTU, and NAT traversal adds UDP overhead. Parameters and peer identities must agree.','Estimate inner MTU and MSS using an explicit overhead assumption.','tunnel','Inspect IKE/IPsec SAs, selectors, counters and path MTU.'],
 'SD-WAN & SDN':['Separate control intent from forwarding state. Central policy can describe application, segmentation and path choices, while data-plane nodes implement forwarding. Controller connectivity does not guarantee overlay reachability. Underlay transport, tunnel MTU and policy must each be validated.','Design a multi-site lab with separate management, transport and service failure checks.','design','Inspect control connections, tunnel state and effective policy.'],
 'Structured Troubleshooting':['Start with the observed failure and scope, gather state, form a testable hypothesis, change one cause and verify. Check both directions of a path. Preserve evidence and compare working and failing examples. Avoid broad changes that merely hide the symptom.','Solve broken configurations and name the evidence that would support each fix.','broken','Collect interfaces, routes, neighbors, policy counters and logs.'],
 'EIGRP & DUAL':['EIGRP’s feasibility condition tests whether a candidate’s reported distance is strictly less than the current feasible distance. A feasible successor supplies a precomputed loop-free alternate. Without one, DUAL can run a diffusing computation. Classic metrics combine minimum bandwidth and cumulative delay with configured K values.','Vary reported and feasible distances; distinguish failure of the condition from proof of a routing loop.','eigrp','show ip eigrp topology all-links'],
 'BGP Path Selection':['Compare candidates for the same prefix. Higher weight/local preference and shorter AS paths are common early Cisco-style criteria, but route validity comes first. Forwarding between prefixes still uses longest-prefix match. MED comparison, multipath and later tie-breaks depend on platform policy.','Make an unreachable next hop lose despite favorable attributes, then change the decisive attribute.','bgp-select','show bgp ipv4 unicast <prefix>'],
 Multicast:['Multicast delivers to receiver groups rather than all hosts. IGMP/MLD signal local membership; multicast routing builds delivery trees. The reverse-path-forwarding check uses the expected path toward a source or rendezvous point and helps prevent loops. Unicast reachability is necessary but not sufficient.','Describe a missing receiver membership and an RPF failure, and identify the separate tables to inspect.','routes','show ip mroute\nshow ip igmp groups'],
 'Route Redistribution':['Redistribution moves routes between control-plane domains and can introduce loops, changed metrics or information loss. Bound the imported prefixes, set appropriate metrics and tag routes to prevent feedback. Administrative preference and longest-prefix behavior can make an unintended route win.','Use a prefix-list to allow intended ranges and reject feedback routes; explain a discard summary route.','prefix','show ip protocols\nshow ip route'],
 'Segment Routing':['Segment Routing encodes a path or service intent as segments. SR-MPLS uses label stacks; SRv6 uses IPv6 segment identifiers and associated behaviors. Topology and policy still require usable underlay reachability. Stack/encapsulation overhead and protection behavior affect design.','Use the MPLS walker to explain push, swap and pop, then describe how an explicit segment list changes path intent.','mpls','Inspect SID advertisements, SR policy and forwarding entries.'],
 'EVPN & VXLAN':['VXLAN carries a Layer 2 segment across a routed IP fabric using a VNI. EVPN distributes reachability and supports multi-tenancy and multi-homing. VTEP reachability, route targets, VNI mapping and MTU must align. A working BGP session does not prove a tenant is correctly connected.','Compute VXLAN overhead and build a validation checklist for VTEP, VNI and tenant reachability.','tunnel','Inspect EVPN routes, NVE peers, VNI state and underlay routes.'],
 'Network Automation':['Automation should preserve intent, scope and verification. Model inputs, stage a diff, validate syntax and dependencies, then check operational state after the change. Use idempotent operations and rollback plans when appropriate. Secrets belong in protected runtime configuration.','Export a reviewed policy and write the pre-change/post-change checks needed before device deployment.','design','Validate intended state against configuration and operational APIs.'],
 'IS-IS':['IS-IS exchanges Layer 2 protocol messages and maintains link-state databases. Level 1 provides intra-area routing; Level 2 connects areas. IIHs form adjacencies, and CSNP/PSNP exchanges help synchronize LSPs. NET addressing and authentication must be compatible.','Walk the IS-IS protocol scenario and compare it with OSPF’s packet transport and area model.','protocol','show isis neighbors\nshow isis database'],
 'Advanced BGP':['Route reflection reduces iBGP mesh requirements but changes path visibility and adds loop-prevention attributes. Communities and route maps implement import/export policy. RPKI origin validation checks origin authorization and max length, while route leaks also require export relationship controls.','Compare a more-specific hijack with an origin-invalid route rejected by policy.','security','show bgp neighbors\nshow bgp ipv4 unicast'],
 'MPLS Traffic Engineering':['Traffic engineering selects paths according to constraints rather than only the IGP shortest path. RSVP-TE and SR policies have distinct control mechanisms. Bandwidth admission, disjointness, failure protection and actual forwarding must be checked. A configured explicit path is only intent until signaling and forwarding succeed.','Fail a topology link and compare the new shortest path with a desired engineered path.','topology','Inspect tunnel/policy state, reservations and label forwarding.']
};
function courseLab(id){let selected=COURSES[id][0];$('surface').innerHTML=card(id.toUpperCase()+' study modules',`<div class="course-grid">${COURSES[id].map((m,i)=>`<button class="module" data-topic="${esc(m)}"><span>MODULE ${String(i+1).padStart(2,'0')}</span><strong>${esc(m)}</strong></button>`).join('')}</div>`)+card('Lesson and lab',out());const show=m=>{selected=m;const lesson=LESSONS[m];$('output').innerHTML=`<div class="eyebrow">${id.toUpperCase()} · ${COURSES[id].indexOf(m)+1} / ${COURSES[id].length}</div><h3>${esc(m)}</h3><p>${esc(lesson[0])}</p><h3>Practice task</h3><p>${esc(lesson[1])}</p><div class="actions"><button id="course-open" class="primary">Open related lab</button><button id="course-next">Next module</button></div><h3>Verification</h3><pre>${esc(lesson[3])}</pre><details class="lesson"><summary>Explain it back</summary><p>Describe the control-plane and forwarding behavior. Name one failure mode, the evidence it creates, and the narrowest fix you would verify.</p></details>`;action('course-open',()=>navigate(lesson[2]));action('course-next',()=>show(COURSES[id][(COURSES[id].indexOf(selected)+1)%COURSES[id].length]));};$('surface').querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>show(b.dataset.topic));show(selected);}
function roadmapLab(){const topics=[['bgp-animation','Establish the session','TCP/179, OPEN, KEEPALIVE and UPDATE'],['bgp-best','Select a usable route','Next-hop reachability and attribute order'],['next-hop','Resolve the next hop','Recursive reachability and next-hop-self'],['prefix','Control prefix policy','Exact, ge/le and route-map actions'],['community','Apply community intent','Tagging and explicit receiver policy'],['regex','Read AS-path policy','Boundaries, origins and transit patterns'],['security','Protect announcements','Origin validation and export relationships'],['broken','Troubleshoot with evidence','Session, policy and forwarding problems']];$('surface').innerHTML=card('BGP learning path',topics.map(([id,t,d],i)=>`<div class="step"><span>${i+1}</span><div style="flex:1"><strong>${t}</strong><p>${d}</p></div><button data-roadmap="${id}">Open lab</button></div>`).join(''));$('surface').querySelectorAll('[data-roadmap]').forEach(b=>b.onclick=()=>navigate(b.dataset.roadmap));}
function aboutLab(){$('surface').innerHTML=card('Param Chawla',`<div style="display:flex;align-items:center;gap:18px;margin-bottom:22px"><span class="avatar" style="width:74px;height:74px;font-size:26px">PC</span><div><h3 style="margin:0">Param Chawla</h3><p style="margin:0">Personal Network Lab</p></div></div><p>A hands-on workspace for exploring addressing, packet exchanges, routing decisions and network troubleshooting.</p><div class="chips"><button data-about="ipv4">Subnetting</button><button data-about="protocol">Protocol simulations</button><button data-about="topology">Network topology</button><button data-about="quiz">Practice</button></div>`)+card('How to use this lab',`<div class="step"><span>1</span><div><strong>Start with a concept</strong><p>Learn the bits, masks and protocol messages before tuning a design.</p></div></div><div class="step"><span>2</span><div><strong>Change one input</strong><p>Observe which result changes and explain why.</p></div></div><div class="step"><span>3</span><div><strong>Practice a failure</strong><p>Check the evidence, choose a fix and verify both directions of the path.</p></div></div>`)+card('Lab scope',`<p>Created for Param Chawla as a personal workspace for networking study and hands-on practice.</p><p>Protocol scenes are educational models. They do not send real packets or replace equipment emulation. The public ASN lookup calls RIPE Stat only when requested. Browser-generated key material stays local.</p><p><a href="https://www.rfc-editor.org/rfc/rfc2328" target="_blank" rel="noopener">OSPFv2 reference</a> · <a href="https://www.rfc-editor.org/rfc/rfc4271" target="_blank" rel="noopener">BGP reference</a> · <a href="https://www.rfc-editor.org/rfc/rfc4291" target="_blank" rel="noopener">IPv6 addressing</a></p>`);$('surface').querySelectorAll('[data-about]').forEach(b=>b.onclick=()=>navigate(b.dataset.about));}

